import { ReactEnv } from '@bitdev/react.react-env';
import findRoot from 'find-root';
import { VitestTester, VitestTask } from '@teambit/vite.vitest-tester';
import type { ReactEnvInterface } from '@bitdev/react.react-env';
import { Compiler } from '@teambit/compiler';
// import { TemplateList } from "@teambit/generator";
// import { ReactComponentTemplate } from "@teambit/react.generator.react-templates";
import { TypeScriptExtractor } from "@teambit/typescript";
import { ReactPreview as RspackReactPreview } from '@teambit/rspack.dev-services.preview.react-preview';
import { rspackTransformer } from './config/rspack.config.js';
// import { ReactVitePreview } from '@bitdev/react.preview.react-vite-preview';
import { EnvHandler } from '@teambit/envs';
import {
  GLOBAL_TYPES_DIR,
  TypescriptCompiler,
  resolveTypes,
  TypescriptTask,
  TypescriptConfigWriter,
} from '@teambit/typescript.typescript-compiler';
import { OxlintLinter, OxlintTask, OxlintConfigWriter } from '@teambit/oxc.linter.oxlint-linter';
import { Linter } from '@teambit/linter';
import { Formatter } from '@teambit/formatter';
import { PrettierConfigWriter, PrettierFormatter } from '@teambit/defender.prettier-formatter';
import { Tester } from '@teambit/tester';
// import { Pipeline } from "@teambit/builder";
import { Preview } from '@teambit/preview';
// import { SchemaExtractor } from "@teambit/schema";
import { PackageGenerator } from '@teambit/pkg';
import { StarterList, TemplateList } from '@teambit/generator';
import { NodeModuleTemplate, ExpressAppTemplate, NodeAppTemplate, NodeEnvTemplate, EntityTemplate, BitAppTemplate, GraphQLServerTemplate, PlatformTemplate } from '@bitdev/node.generators.node-templates';
import { NodeWorkspaceStarter, PlatformFeatureStarter } from '@bitdev/node.generators.node-starters';
import { CAPSULE_ARTIFACTS_DIR, Pipeline } from '@teambit/builder';
import { ConfigWriterList } from '@teambit/workspace-config-files';
import { SchemaExtractor } from '@teambit/schema';
import { createRequire } from "node:module";
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const esmRequire = createRequire(import.meta.url);
const fileFolderPath = dirname(fileURLToPath(import.meta.url));

export class NodeEnv extends ReactEnv implements ReactEnvInterface {
  /**
   * name of the environment. used for friendly mentions across bit.
   */
  name = 'node-env';

  type = 'node';

  protected dirName = dirname(fileURLToPath(import.meta.url));

  /**
   * icon for the env. use this to build a more friendly env.
   * uses node by default.
   */
  icon = 'https://static.bit.dev/extensions-icons/nodejs.svg';

  /**
   * return an instance of a Compiler. use components like typescript-compiler (teambit.typescript/typescript-compiler)
   * or our babel-compiler (teambit.compilation/babel-compiler).
   * @example
   * return TypescriptCompiler.from({
   *  tsconfig: esmRequire.resolve("./config/tsconfig.json"), // path to tsconfig.json
   *  types: resolveTypes(fileFolderPath, ["./types"]),
   *  typescript,
   * });
   */

  // TODO: make sure we only run compiler once @david.
  compiler(): EnvHandler<Compiler> {
    return TypescriptCompiler.from({
      esm: true,
      tsconfig: this.tsconfigPath,
      types: this.types
    });
  }

  /**
   * returns an instance of a Bit tester implementation. use components like mocha-tester or
   * jest-tester or [build your own](http/://bit.dev/reference/testing/set-up-tester).
   */
  tester(): EnvHandler<Tester> {
    return VitestTester.from({
      config: this.vitestConfigPath
    });
    // return MochaTester.from({
    //   mochaConfigPath: esmRequire.resolve('./config/.mocharc.js'),
    //   babelConfig: esmRequire.resolve('./config/mocha-babel-config.js'),
    // });
  }

  /**
   * return an instance of a Bit preview instance. used for preview purposes.
   * base preview is a general purpose rspack preview.
   */
  preview(): EnvHandler<Preview> {
    return RspackReactPreview.from({
      previewConfig: {
        splitComponentBundle: false,
        strategyName: 'component',
      },
      transformers: [rspackTransformer],
    });
  }

  /**
   * returns an instance of the default linter.
   * config files would be used to validate coding standards in components.
   * bit will write the minimum required files in any workspace to optimize
   * for dev experience.
   */
  linter(): EnvHandler<Linter> {
    return OxlintLinter.from({
      binDir: this.envCurrentPath,
      oxlintNodeOptions:{
        configPath: this.oxlintConfigPath,
        tsconfigPath: this.tsconfigPath,
        typeAware: true,
      }
    });
  }

  /**
   * used by bit's formatter. helps to standardize and automate
   * code styling. can be used a build task or using bit lint and common
   * ides.
   */
  formatter(): EnvHandler<Formatter> {
    return PrettierFormatter.from({
      configPath: this.prettierConfigPath,
    });
  }

  /**
   * a list of starters for new projects. this helps create a quick and
   * standardized
   */
  starters() {
    return StarterList.from([
      NodeWorkspaceStarter.from(),
      PlatformFeatureStarter.from()
    ]);
  }

  /**
   * set a list of component templates to use across your
   * workspaces. new workspaces would be set to include
   * your envs by default.
   */
  generators() {
    return TemplateList.from([
      NodeModuleTemplate.from(),
      EntityTemplate.from(),
      ExpressAppTemplate.from(),
      GraphQLServerTemplate.from(),
      NodeAppTemplate.from(),
      BitAppTemplate.from(),
      PlatformTemplate.from(),
      NodeEnvTemplate.from()
    ]);
  }

  /**
   * define the build pipeline for a component.
   * pipelines are optimized for performance and consistency.
   * making sure every component is independently built and tested.
   */
  build() {
    return Pipeline.from([
      TypescriptTask.from({
        tsconfig: this.tsconfigPath,
        types: this.types
      }),
      VitestTask.from({
        config: this.vitestConfigPath,
      }),
    ]);
  }

  /**
   * add build tasks to execute upon [snap](https://bit.dev/docs/snaps).
   * use the snap pipeline for staging and test deployments
   */
  snap() {
    return Pipeline.from([]);
  }

  /**
   * add build tasks to execute upon [tag](https://bit.dev/docs/tags).
   * use the tag pipeline for deployments, or other tasks required for
   * publishing a semantic version for a component.
   */
  tag() {
    return Pipeline.from([]);
  }

  /**
   * configure and control the packaging process of components.
   */
  package() {
    return PackageGenerator.from({
      packageJson: {
        main: 'dist/{main}.js',
        types: '{main}.ts',
        type: 'module',
      },
      npmIgnore: this.npmIgnore,
    });
  }

  /**
   * add configuration writers to the workspace, to sync IDE features with tools operated by Bit
   */
  workspaceConfig(): ConfigWriterList {
    return ConfigWriterList.from([
      TypescriptConfigWriter.from({
        tsconfig: this.tsconfigPath,
        types: this.types
      }),
      OxlintConfigWriter.from({
        configPath: this.oxlintConfigPath,
      }),
      PrettierConfigWriter.from({
        configPath: this.prettierConfigPath,
      })
    ]);
  }

  /**
   * returns an instance of the default TypeScript extractor.
   * used by default for type inference for both JS and TS.
   */
  schemaExtractor(): EnvHandler<SchemaExtractor> {
    return TypeScriptExtractor.from({
      tsconfig: this.tsconfigPath,
    });
  }

  protected envCurrentPath = fileFolderPath;

  protected tsconfigPath = esmRequire.resolve('./config/tsconfig.json');
  
  protected tsTypesPath = './types';

  protected get types() {
    const packagePath = esmRequire.resolve('@teambit/typescript.typescript-compiler');
    const packageRoot = findRoot(packagePath);

    return [
      ...resolveTypes(this.envCurrentPath, [this.tsTypesPath]),
      ...resolveTypes(packageRoot,[GLOBAL_TYPES_DIR]),
    ];
  }

  protected vitestConfigPath = esmRequire.resolve('./config/vitest.config.mjs');

  protected oxlintConfigPath = esmRequire.resolve('./config/oxlintrc.json');
  
  protected prettierConfigPath = esmRequire.resolve('./config/prettier.config.cjs');
  
  protected prettierExtensions = [
    '.js',
    '.jsx',
    '.ts',
    '.tsx',
    '.mjs',
    '.cjs',
    '.json',
    '.css',
    '.scss',
    '.md',
    '.mdx',
    '.html',
    '.yml',
    '.yaml',
  ];

  protected previewMounter = esmRequire.resolve('./preview/mounter');

  protected previewViteConfig = esmRequire.resolve('./config/vite.config.mjs')

  /**
   * Default npm ignore paths.
   * Will ignore the "artifacts" directory by default.
   */
  npmIgnore = [`${CAPSULE_ARTIFACTS_DIR}/`];
}

export default new NodeEnv();
